retrieval.cypher:
MATCH (a:PlantItem {tag: 'P-1901A'}), (b:PlantItem {tag: 'D-1901'})
RETURN EXISTS {
  MATCH p = shortestPath((a)-[:line_to*1..]->(b))
} AS reachable

